export function trackedNodeModulesPaths(paths: string[]): string[] {
  return paths.filter((p) => p.split('/').includes('node_modules'));
}

export async function untrackNodeModules(git: GitRunner): Promise<string[]> {
  const tracked = trackedNodeModulesPaths((await git(['ls-files'])).split('\n').filter(Boolean));
  const roots = [...new Set(tracked.map((p) => { const s = p.split('/'); return s.slice(0, s.indexOf('node_modules') + 1).join('/'); }))];
  if (roots.length) await git(['rm', '-r', '--cached', '--ignore-unmatch', '--', ...roots]);
  return roots;
}

export async function assertNoTrackedNodeModules(git: GitRunner): Promise<void> {
  const bad = trackedNodeModulesPaths((await git(['ls-files'])).split('\n').filter(Boolean));
  if (bad.length) throw new Error(`${bad.length} tracked node_modules paths:\n${bad.slice(0, 10).join('\n')}`);
}
